INSERT INTO `testimonials` VALUES (1,'Omar Hassan','Spice Buyer, United Arab Emirates','Cardamom and cumin arrived clean, well graded, and on the date we agreed. Packing held up through the sea shipment.',5),(2,'Elena Kovacs','Import Manager, Germany','Basmati rice matched the sample. Documents were ready before the container moved, which made customs simple for us.',5),(3,'Daniel Okonkwo','Procurement Lead, Nigeria','We ordered turmeric and black pepper together. Quality was consistent across both lots, and the team answered quickly.',5),(4,'Mei Lin','Tea Buyer, Singapore','Orange pekoe and green tea kept their leaf and aroma. The grades were exactly what we had approved.',5),(5,'Carlos Mendes','Dry Fruit Importer, Portugal','Almonds and cashews were sorted properly and packed for a long transit. We have already placed a repeat order.',5);
